sys_script_include.script:
var EWTEmployeeQualifier = Class.create();
EWTEmployeeQualifier.prototype = {
    initialize: function() {},

    getQualifier: function(current) {
        var isReplacement = current.getValue('is_replacement');
        if (isReplacement == 'true' || isReplacement == '1' || isReplacement === true) {
            return 'active=true';
        }

        var rpId = current.getValue('resource_plan');
        if (!rpId) {
            return 'sys_id=NULL';
        }

        var rp = new GlideRecord('x_2316178_contin_0_res_plan');
        if (!rp.get(rpId)) {
            return 'sys_id=NULL';
        }

        var groupId = rp.getValue('assignment_group');
        if (!groupId) {
            return 'active=true';
        }

        var userIds = [];
        var gm = new GlideRecord('sys_user_grmember');
        gm.addQuery('group', groupId);
        gm.query();
        while (gm.next()) {
            userIds.push(gm.getValue('user'));
        }

        if (userIds.length === 0) {
            return 'sys_id=NULL';
        }

        return 'sys_idIN' + userIds.join(',');
    },

    type: 'EWTEmployeeQualifier'
};
